import React from 'react';
import type { Orientation } from '../../../../core/types/orientation.js';
import type { StylingProps } from '../../../../core/types/styling-props.js';
import { Dimensions } from '../../types/dimensions.js';
/**
 *  @internal
 */
export type OverrideRatioFunction = (orientation: Orientation, width: number, height: number) => Dimensions;
/**
 * @internal
 * Relative sizes for the legend in the range [0-1].
 * Example:
 * 0.2 represent the 20% of the whole container (plot + legend).
 */
export interface ChartLayoutLegendSizes {
    minWidth: number;
    minHeight: number;
    maxWidth: number;
    maxHeight: number;
}
/**
 *  @internal
 */
export interface ChartLayoutLegendProps {
    orientation?: 'auto' | 'bottom' | 'right';
    ratio?: number;
    overrideRatio?: OverrideRatioFunction;
    hidden?: boolean;
    sizes?: ChartLayoutLegendSizes;
}
/**
 *  @internal
 */
export interface ChartLayoutProps extends StylingProps {
    chartWidth?: string | number;
    chartHeight?: string | number;
    squaredPlotArea?: boolean;
    resizable?: boolean;
    isEmpty?: boolean;
    emptyState?: React.ReactNode;
    errorState?: React.ReactNode | ((message: string) => JSX.Element);
    legendConfig?: ChartLayoutLegendProps;
    showLoader?: boolean;
}
/**
 *  @internal
 */
export type ChartLayoutDimensions = Dimensions & {
    wrapperHeight: number;
    padding: {
        top: number;
        bottom: number;
        left: number;
        right: number;
    };
};
